-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 7
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 7 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 07', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 07 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-07.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga a diferença entre monitorar e controlar os testes.', 0.2, '**Monitorar** é **acompanhar** o andamento dos testes comparando com o plano; **controlar** é **agir** quando o andamento foge do previsto (replanejar, priorizar, corrigir).', 'Palavras-chave: monitorar = acompanhar/comparar com o plano; controlar = agir/replanejar. Nota cheia (0,2): as duas definições. Metade (0,1): só uma. Zero (0): trata as duas como a mesma coisa.'),
      (v_atividade, 1, 2, 'Cite três métricas que ajudam a monitorar os testes e o que cada uma mostra.', 0.4, 'Três entre: **casos executados × planejados** (andamento da execução); **taxa de aprovação** (quantos testes passam); **defeitos abertos por gravidade** (risco ainda presente); **cobertura de código** (quanto do código a suíte executa); **testes instáveis (flaky)** (confiança na suíte); **tempo de execução** (custo de rodar a suíte).', 'Palavras-chave: as métricas da tabela da aula com o que mostram. Nota cheia (0,4): três métricas com o que cada uma mostra. Metade (0,2): três métricas sem explicação, ou duas com explicação. Zero (0): uma métrica ou nenhuma.'),
      (v_atividade, 1, 3, 'Explique por que as decisões de controle precisam se apoiar em métricas, e não na impressão da equipe.', 0.4, 'A impressão **não é verificável** e muda de pessoa para pessoa; a métrica é um **dado objetivo** que mostra **onde** está o problema e **quanto** ele é grave (por exemplo, faltam 12 casos de checkout). Com dados, a decisão (priorizar, bloquear a entrega, corrigir) pode ser **justificada e acompanhada**.', 'Palavras-chave: dado objetivo × impressão; mostra onde e quanto; decisão justificada. Nota cheia (0,4): explicação com o ganho da métrica. Metade (0,2): "métrica é melhor" sem dizer por quê. Zero (0): diz que a impressão basta.'),
      (v_atividade, 2, 1, 'Diga qual dos três sinais é o mais grave para a publicação e por quê.', 0.2, 'Os **2 defeitos críticos abertos no pagamento**, porque mostram um **risco ainda presente** na parte que lida com o dinheiro do cliente: com eles, a versão **não pode ser publicada**.', 'Palavras-chave: defeitos críticos no pagamento; risco presente; não publicar. Nota cheia (0,2): sinal certo + motivo. Metade (0,1): sinal certo sem motivo. Zero (0): outro sinal.'),
      (v_atividade, 2, 2, 'Escreva a ação de controle para cada um dos três sinais.', 0.4, '**Taxa de aprovação caiu de 98% para 80%:** bloquear a entrega e investigar o que quebrou. **2 defeitos críticos no pagamento:** não publicar até corrigir e testar de novo. **Tempo de 2 para 9 minutos:** separar os testes E2E por etapa (rodar os rápidos primeiro) e procurar testes lentos.', 'Palavras-chave: bloquear e investigar; não publicar; separar E2E/etapas. Nota cheia (0,4): três ações coerentes. Metade (0,2): duas ações. Zero (0): uma ação ou nenhuma.'),
      (v_atividade, 2, 3, 'Explique por que três testes instáveis (flaky) devem ser corrigidos antes de a equipe criar testes novos.', 0.4, 'Testes flaky **passam e falham sem mudança no código**, então a equipe **deixa de confiar** no resultado da suíte e passa a ignorar falhas, inclusive as verdadeiras. Criar testes novos numa suíte em que ninguém confia **não aumenta a proteção**; primeiro é preciso **recuperar a confiança** corrigindo os instáveis.', 'Palavras-chave: resultado sem mudança no código; perda de confiança; falhas verdadeiras ignoradas. Nota cheia (0,4): explicação completa. Metade (0,2): só define flaky. Zero (0): manda ignorar os flaky.'),
      (v_atividade, 3, 1, 'Escreva o comando que instala o provedor de cobertura v8 e o comando que cria o script test:coverage.', 0.2, 'npm install -D @vitest/coverage-v8 e npm pkg set scripts.test:coverage="vitest run --coverage"', 'Palavras-chave: @vitest/coverage-v8 com -D; script test:coverage com vitest run --coverage. Nota cheia (0,2): os dois comandos. Metade (0,1): só um. Zero (0): nenhum correto.'),
      (v_atividade, 3, 2, 'Escreva o vitest.config.js com o ambiente jsdom e a cobertura com provedor v8, relatórios text e html e os arquivos de src.', 0.4, 'import { defineConfig } from ''vitest/config''; export default defineConfig({ test: { environment: ''jsdom'', coverage: { provider: ''v8'', reporter: [''text'', ''html''], include: [''src/**/*.js''] } } });', 'Palavras-chave: defineConfig de vitest/config; test.environment jsdom; coverage.provider v8; reporter text e html; include src. Nota cheia (0,4): configuração completa. Metade (0,2): falta um item (reporter ou include) ou coverage fora de test. Zero (0): sem o bloco coverage.'),
      (v_atividade, 3, 3, 'Diga o que o comando npm run test:coverage mostra e gera e explique para que serve cada um dos dois relatórios.', 0.4, 'Mostra a **tabela de cobertura no terminal** (relatório text) e gera a pasta **coverage/index.html** (relatório html). A tabela dá os **quatro percentuais** por arquivo para uma visão rápida; o HTML mostra **linha por linha** o que rodou e o que não rodou (vermelho, marcadores I e E), para achar os pontos cegos.', 'Palavras-chave: tabela no terminal; coverage/index.html; visão rápida × linha por linha. Nota cheia (0,4): os dois relatórios com a utilidade de cada um. Metade (0,2): os dois sem utilidade, ou só um com utilidade. Zero (0): não cita os relatórios.'),
      (v_atividade, 4, 1, 'Diga a pergunta que cada métrica responde: statements, branches, functions e lines.', 0.2, '**Statements:** quantas instruções rodaram? **Branches:** cada if foi testado no lado verdadeiro e no falso? **Functions:** todas as funções foram chamadas? **Lines:** quantas linhas rodaram?', 'Palavras-chave: instruções; verdadeiro e falso do if; funções chamadas; linhas. Nota cheia (0,2): as quatro. Metade (0,1): duas ou três. Zero (0): uma ou nenhuma.'),
      (v_atividade, 4, 2, 'Explique, com um exemplo de if, como um código pode ter 100% de linhas e 50% de branches.', 0.4, 'Exemplo: function desconto(total) { if (total > 100) total = total - 10; return total; } — Um único teste com total 200 executa **todas as linhas** (100% de lines), mas só testa o lado **verdadeiro** do if; o lado **falso** (total até 100, sem desconto) **nunca foi testado**, por isso branches fica em 50%.', 'Palavras-chave: exemplo com if; um teste passa por todas as linhas; só um lado do if testado. Nota cheia (0,4): exemplo + explicação dos dois lados. Metade (0,2): explicação sem exemplo, ou exemplo sem explicação. Zero (0): explicação errada.'),
      (v_atividade, 4, 3, 'Explique por que branches é a métrica mais exigente e o que o resultado do módulo indica.', 0.4, '**Branches** é a mais exigente porque obriga a testar **cada lado de cada condição**: mostra as **decisões que a suíte nunca testou**, mesmo quando todas as linhas rodaram. No módulo, 100% de linhas com 50% de branches indica que **metade dos caminhos das condições não foi testada**: o módulo **não está bem testado**.', 'Palavras-chave: cada lado da condição; decisões nunca testadas; metade dos caminhos sem teste. Nota cheia (0,4): motivo + leitura do resultado. Metade (0,2): só uma das partes. Zero (0): diz que 100% de linhas basta.'),
      (v_atividade, 5, 1, 'Diga o que significam, no relatório HTML, as linhas em vermelho e os marcadores I e E.', 0.2, 'Linhas em **vermelho** **não rodaram** em nenhum teste; o marcador **I** indica que o caminho do **if** não foi testado e o **E**, que o do **else** não foi testado.', 'Palavras-chave: vermelho = não rodou; I = if; E = else. Nota cheia (0,2): os três. Metade (0,1): um ou dois. Zero (0): nenhum.'),
      (v_atividade, 5, 2, 'Liste os três caminhos da função que o relatório vai apontar como não testados.', 0.4, '1) **Cupom expirado** (erro "Cupom expirado"). 2) **Valor mínimo não atingido** (erro "Valor mínimo não atingido"). 3) **Cupom de valor fixo** (Math.max(total - cupom.valor, 0)).', 'Palavras-chave: expirado; valor mínimo; valor fixo. Nota cheia (0,4): os três caminhos. Metade (0,2): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 5, 3, 'Diga qual caminho deve ser testado primeiro pelo risco e justifique pelo que aconteceria com o pedido sem o Math.max.', 0.4, 'Primeiro o **cupom de valor fixo maior que o total**, porque é o caminho de **maior risco**: sem o Math.max, a loja geraria um **pedido com valor negativo** (por exemplo, total 30 com cupom de 50 daria -20), um prejuízo real.', 'Palavras-chave: valor fixo maior que o total; risco; valor negativo. Nota cheia (0,4): caminho certo + justificativa pelo valor negativo. Metade (0,2): caminho certo sem justificativa. Zero (0): outro caminho ou sem justificativa pelo risco.'),
      (v_atividade, 6, 1, 'Escreva as constantes HOJE e CUPOM_FIXO (tipo fixo, valor 50, sem valor mínimo, validade no fim do ano) usadas pelos testes.', 0.2, 'const HOJE = new Date(''2026-11-05''); const CUPOM_FIXO = { tipo: ''fixo'', valor: 50, valorMinimo: 0, validade: ''2026-12-31'' };', 'Palavras-chave: HOJE com data fixa (new Date com data escrita); CUPOM_FIXO com tipo fixo, valor 50, valorMinimo 0 e validade. Nota cheia (0,2): as duas constantes completas. Metade (0,1): falta um campo ou a data não é fixa. Zero (0): sem as constantes.'),
      (v_atividade, 6, 2, 'Escreva os testes "nunca deixa o total negativo com cupom de valor fixo" e "recusa cupom vencido".', 0.4, 'import { describe, it, expect } from ''vitest''; import { aplicarCupom } from ''../src/servicos/carrinho.js''; describe(''aplicarCupom'', () => { it(''nunca deixa o total negativo com cupom de valor fixo'', () => { expect(aplicarCupom(30, CUPOM_FIXO, HOJE)).toBe(0); }); it(''recusa cupom vencido'', () => { const cupomVencido = { ...CUPOM_FIXO, validade: ''2026-10-01'' }; expect(() => aplicarCupom(100, cupomVencido, HOJE)).toThrow(''Cupom expirado''); }); });', 'Palavras-chave: aplicarCupom(30, CUPOM_FIXO, HOJE) com toBe(0); cupom com validade anterior a HOJE; expect com função anônima e toThrow(''Cupom expirado''). Nota cheia (0,4): os dois testes corretos. Metade (0,2): só um teste correto, ou toThrow sem a função anônima. Zero (0): nenhum teste correto.'),
      (v_atividade, 6, 3, 'Explique por que a data HOJE precisa ser fixa no teste de validade do cupom.', 0.4, 'Com a **data real** (new Date() sem valor), o resultado **muda com o tempo**: o teste **passaria hoje e falharia no ano que vem**, quando a validade de 2026-12-31 já tiver passado, sem nenhuma mudança no código. Com HOJE fixa, o teste dá **sempre o mesmo resultado**.', 'Palavras-chave: data real muda; passa hoje e falha depois; sempre o mesmo resultado. Nota cheia (0,4): explicação completa. Metade (0,2): "para não dar erro" sem dizer o motivo. Zero (0): diz que tanto faz.'),
      (v_atividade, 7, 1, 'Diga qual pergunta a avaliação dos resultados responde.', 0.2, '**Os critérios de saída do plano foram atingidos?** — respondida com os dados dos testes, não com impressão.', 'Palavras-chave: critérios de saída do plano; com dados. Nota cheia (0,2): pergunta certa. Metade (0,1): "ver se os testes passaram" sem citar os critérios do plano. Zero (0): resposta sem relação.'),
      (v_atividade, 7, 2, 'Cite quatro perguntas dos critérios de saída do plano que você confere antes de recomendar a publicação.', 0.4, '1) **Todos os casos de alto risco** foram executados e passaram? 2) A **cobertura atingiu a meta** do plano (ex.: ≥ 70% na UC; meta da turma 80%)? 3) Há **defeito crítico aberto**? 4) A suíte está **estável** (nenhum flaky)?', 'Palavras-chave: alto risco; meta de cobertura; defeito crítico; estabilidade/flaky. Nota cheia (0,4): as quatro perguntas. Metade (0,2): duas ou três. Zero (0): uma ou nenhuma.'),
      (v_atividade, 7, 3, 'Escreva a sua recomendação para esta loja (publicar ou não), com a meta por módulo e a justificativa pelo risco.', 0.4, '**Não publicar.** Os 92% gerais escondem o **módulo de pagamento com só 31% de branches**: o número alto vem de testes simples de componentes visuais. Recomendo cobrir os desvios de **recusa do cartão** e de **pagamento duplicado** e adotar **meta por módulo** (pagamento ≥ 90%), porque o pagamento é a parte de **maior risco** da loja.', 'Palavras-chave: não publicar; 31% de branches no pagamento; número geral engana; meta por módulo (pagamento ≥ 90% ou valor alto justificado); risco. Nota cheia (0,4): recomendação + meta por módulo + justificativa pelo risco. Metade (0,2): "não publicar" sem meta ou sem justificativa. Zero (0): recomenda publicar.'),
      (v_atividade, 8, 1, 'Diga o que a cobertura mede e o que ela não mede.', 0.2, 'A cobertura mede o que **rodou** durante os testes; ela **não mede o que foi conferido** (se havia expect e se o expect era bom).', 'Palavras-chave: mede o que rodou; não mede o que foi conferido. Nota cheia (0,2): as duas partes. Metade (0,1): só uma. Zero (0): diz que cobertura mede a qualidade dos testes.'),
      (v_atividade, 8, 2, 'Escreva o caso de borda (teste) que encontra o defeito, com cupom de valor mínimo 100 e total 100.', 0.4, 'it(''aceita total exatamente igual ao valor mínimo'', () => { const cupom = { tipo: ''fixo'', valor: 10, valorMinimo: 100, validade: ''2026-12-31'' }; expect(aplicarCupom(100, cupom, HOJE)).toBe(90); }); — Com o defeito (<=), o teste falha com "Valor mínimo não atingido", mostrando o erro no valor-limite.', 'Palavras-chave: total igual ao valor mínimo (100 e 100); cupom válido em relação a HOJE; expect do total com desconto (ou not.toThrow). Nota cheia (0,4): teste correto do valor-limite. Metade (0,2): valor-limite certo sem verificação correta, ou verificação certa com valores diferentes do limite. Zero (0): não testa o limite.'),
      (v_atividade, 8, 3, 'Explique por que 100% de linhas não garante que o requisito foi atendido e com o que a cobertura deve ser cruzada.', 0.4, 'Porque a cobertura só olha o **código que existe**: um **requisito esquecido não tem código**, então **não aparece no relatório**, e um teste **sem expect** cobre linhas sem verificar nada. Por isso a cobertura é cruzada com a **matriz de rastreabilidade** (aula 2), que liga cada requisito aos seus casos de teste.', 'Palavras-chave: requisito esquecido não tem código; teste sem expect; matriz de rastreabilidade. Nota cheia (0,4): motivo + matriz de rastreabilidade. Metade (0,2): só o motivo ou só a matriz. Zero (0): diz que 100% garante o requisito.'),
      (v_atividade, 9, 1, 'Diga o que é uma suíte fácil de manter.', 0.2, 'É a suíte que a equipe **entende e altera sem medo**: nomes claros, dados com nome, testes independentes e curtos e testes pelo comportamento.', 'Palavras-chave: entende e altera sem medo. Nota cheia (0,2): definição com a ideia de entender e alterar. Metade (0,1): "suíte organizada" sem explicar. Zero (0): confunde com suíte grande.'),
      (v_atividade, 9, 2, 'Reescreva o teste com um nome que descreve o comportamento e com os dados em constantes com nome.', 0.4, 'const HOJE = new Date(''2026-11-05''); const CUPOM_FIXO = { tipo: ''fixo'', valor: 50, valorMinimo: 0, validade: ''2026-12-31'' }; it(''nunca deixa o total negativo com cupom de valor fixo'', () => { expect(aplicarCupom(30, CUPOM_FIXO, HOJE)).toBe(0); });', 'Palavras-chave: nome que descreve o comportamento; constantes com nome para a data e o cupom; mesma verificação toBe(0). Nota cheia (0,4): nome + constantes + verificação. Metade (0,2): só o nome ou só as constantes. Zero (0): teste igual ao original.'),
      (v_atividade, 9, 3, 'Explique duas práticas que evitam que trocar o CSS ou reorganizar o código interno quebre a suíte.', 0.4, 'Duas entre: **testar pelo comportamento** (o que o usuário vê e o que a função devolve), e não por detalhes internos; **não usar classe de estilo** como seletor (preferir papel, rótulo ou data-testid); **testes independentes e curtos, um comportamento por teste**, para que uma mudança quebre só o teste ligado a ela.', 'Palavras-chave: testar pelo comportamento; sem seletor por classe de CSS; um comportamento por teste. Nota cheia (0,4): duas práticas explicadas. Metade (0,2): uma prática. Zero (0): nenhuma prática certa.'),
      (v_atividade, 10, 1, 'Diga qual opção do coverage define as metas mínimas.', 0.2, 'A opção **thresholds**, dentro de **coverage**.', 'Palavras-chave: thresholds. Nota cheia (0,2): thresholds. Metade (0,1): descreve a ideia sem o nome da opção. Zero (0): outra opção.'),
      (v_atividade, 10, 2, 'Escreva o bloco coverage com o provedor v8 e as metas de 80% para as quatro métricas.', 0.4, 'coverage: { provider: ''v8'', thresholds: { statements: 80, branches: 80, functions: 80, lines: 80 } }', 'Palavras-chave: provider v8; thresholds com statements, branches, functions e lines em 80. Nota cheia (0,4): bloco completo. Metade (0,2): faltam métricas ou thresholds fora de coverage. Zero (0): sem thresholds.'),
      (v_atividade, 10, 3, 'Explique o que acontece com o npm run test:coverage quando a cobertura fica abaixo da meta e como isso protege a loja quando o comando roda no pipeline.', 0.4, 'O comando **termina com erro** quando alguma métrica fica abaixo da meta. No pipeline (GitHub Actions, aula 9), esse erro **deixa a verificação vermelha e bloqueia o merge**, então a cobertura **não cai sem que a equipe perceba** e nenhum código com menos testes chega à loja.', 'Palavras-chave: termina com erro; pipeline bloqueia o merge; a queda não passa despercebida. Nota cheia (0,4): as duas partes. Metade (0,2): só o erro ou só o bloqueio. Zero (0): diz que só mostra um aviso.');
end $$;
